package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import com.mojang.blaze3d.vertex.*;import team.creative.littletiles.client.render.overlay.PreviewRenderer;import team.creative.littletiles.client.render.mc.MeshDataExtender;import team.creative.littletiles.common.math.box.collection.LittleBoxes;import it.unimi.dsi.fastutil.longs.LongArrayList;
public final class LinesOnlyOutlineDrag {
 private static final java.util.Map<MeshData,Boolean> meshes=java.util.Collections.synchronizedMap(new java.util.WeakHashMap<>());
 public static boolean contains(MeshData mesh){return meshes.containsKey(mesh);}
 public static PreviewRenderer.BoxRenderResult mark(PreviewRenderer.BoxRenderResult result){if(result!=null&&result.data()!=null)meshes.put(result.data(),Boolean.TRUE);return result;}
 public static PreviewRenderer.BoxRenderResult build(PreviewRenderer renderer,LittleBoxes boxes){var faces=PolygonDragFaces.extract(boxes);if(faces==null)return generic(renderer,boxes);if(faces.isEmpty())return generic(renderer,boxes);
 var context=PolygonVoxelContext.take();int[] min=context.min();long sy=context.sy(),sz=context.sz(),yz=sy*sz;long[] stride={yz,sz,1};var occupied=context.cells();var edges=new LongArrayList[]{new LongArrayList(),new LongArrayList(),new LongArrayList()};long sx=0;for(var b:boxes.all())sx=Math.max(sx,(long)b.maxX-min[0]+2);double scale=boxes.grid.pixelLength;
 ByteBufferBuilder lineOwner=null;try{for(var f:faces){int n=f[0],a=f[3],b=f[4];int[] q=new int[3];q[n]=f[2]-f[1];q[a]=f[5];q[b]=f[7];long own=((long)q[0]-min[0]+1)*yz+((long)q[1]-min[1]+1)*sz+(long)q[2]-min[2]+1;long normal=f[1]==0?-stride[n]:stride[n];for(int tangent:new int[]{a,b})if(n<tangent)for(int sign:new int[]{-1,1})if(((f[9]&(1<<(tangent*2+(sign>0?1:0))))==0)||occupied.contains(own+sign*stride[tangent]+normal)){int edge=3-n-tangent;long vertex=own+(f[1]==1?stride[n]:0)+(sign==1?stride[tangent]:0);edges[edge].add(vertex);}}
lineOwner=renderer.createBuffer();var mesh=PolygonOutlineLines.write(lineOwner,edges,sx,sy,sz,min,scale);if(mesh instanceof MeshDataExtender e)e.keepAlive(true);var result=new PreviewRenderer.BoxRenderResult(boxes,boxes.pos,lineOwner,mesh);return mark(result);
 }catch(Throwable t){if(lineOwner!=null)lineOwner.close();throw t;}}
 public static PreviewRenderer.BoxRenderResult generic(PreviewRenderer renderer,LittleBoxes boxes){var faces=DragExteriorMesh.faces(boxes);if(faces==null)return null;var edges=new PrimitiveGridOutlineEdges();for(var f:faces)edges.face(f,boxes.grid.pixelLength);var owner=renderer.createBuffer();try{var builder=new BufferBuilder(owner,VertexFormat.Mode.DEBUG_LINES,DefaultVertexFormat.POSITION_COLOR);edges.finish(s->{builder.addVertex((float)s.a().x(),(float)s.a().y(),(float)s.a().z()).setColor(-1);builder.addVertex((float)s.b().x(),(float)s.b().y(),(float)s.b().z()).setColor(-1);});var mesh=builder.build();if(mesh!=null)((MeshDataExtender)(Object)mesh).keepAlive(true);return mark(new PreviewRenderer.BoxRenderResult(boxes,boxes.pos,owner,mesh));}catch(Throwable t){owner.close();throw t;}}
}
